import { Component, computed, inject, input, output, signal } from '@angular/core';
import { Session } from '../../core/session';
import { GRADES, Grade } from './people.service';
import { Rate, RatesService, rateOn } from './rates.service';

const PCT = /^\d{1,5}(\.\d{1,2})?$/;

// The rates of each grade on the sheet, each from its from-date, with the one in force on the
// sheet's today, and the form that sets a grade's rate from a date.
@Component({
  selector: 'app-rates',
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form (submit)="submit($event)" aria-label="Rate" data-testid="rate-form">
        <label for="rate-form-grade">Grade</label>
        <select
          id="rate-form-grade"
          data-testid="rate-form-grade"
          [value]="grade()"
          (change)="grade.set(gradeOf($event)); error.set(null)"
        >
          @for (g of grades; track g) {
            <option [value]="g" [selected]="g === grade()">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input
          id="rate-form-pct"
          data-testid="rate-form-pct"
          inputmode="decimal"
          [value]="pct()"
          (input)="pct.set(value($event)); error.set(null)"
        />
        <label for="rate-form-from">From</label>
        <input
          id="rate-form-from"
          type="date"
          data-testid="rate-form-from"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as message) {
          <p role="alert" class="error" data-testid="rate-form-error">{{ message }}</p>
        }
      </form>
      <table data-testid="rate-list">
        <caption>Rate in force on {{ session.today() }}</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <td>{{ g }}</td>
              <td [attr.data-testid]="'rate-current-' + g">
                <span [attr.data-testid]="currentOf(g) === null ? null : 'rate-pct'">{{ currentOf(g) ?? 'n/a' }}</span>
              </td>
            </tr>
          }
        </tbody>
      </table>
      @if (sorted().length > 0) {
        <table data-testid="rate-history">
          <caption>All rates</caption>
          <thead>
            <tr>
              <th scope="col">Grade</th>
              <th scope="col">From</th>
              <th scope="col">Rate (%)</th>
            </tr>
          </thead>
          <tbody>
            @for (r of sorted(); track r.grade + '-' + (r.from ?? 'start')) {
              <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
                <td>{{ r.grade }}</td>
                <td data-testid="rate-from">{{ r.from ?? 'the start' }}</td>
                <td data-testid="rate-pct">{{ r.pct }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
    </section>
  `,
  styles: `
    form {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.5rem;
    }
    .error {
      color: #a40000;
      margin: 0;
    }
    table {
      border-collapse: collapse;
      margin-bottom: 1rem;
    }
    caption {
      text-align: left;
      font-weight: bold;
    }
    th,
    td {
      text-align: left;
      padding: 0.25rem 0.75rem 0.25rem 0;
    }
  `,
})
export class Rates {
  protected readonly session = inject(Session);
  private readonly service = inject(RatesService);

  /** The sheet's rates. */
  readonly rates = input.required<Rate[]>();
  /** The rates by grade, then by from-date (one with none first). */
  protected readonly sorted = computed(() =>
    [...this.rates()].sort(
      (a, b) => a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? ''),
    ),
  );
  /** A grade's rate was set. */
  readonly saved = output<Rate>();

  protected readonly grades = GRADES;
  protected readonly grade = signal<Grade>('A');
  protected readonly pct = signal('');
  protected readonly from = signal('');
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer; another submit meanwhile is ignored. */
  private submitting = false;

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected gradeOf(event: Event): Grade {
    return (event.target as HTMLSelectElement).value as Grade;
  }

  /** The grade's rate in force on the sheet's today. */
  protected currentOf(grade: Grade): string | null {
    const today = this.session.today();
    return today === null ? null : rateOn(this.rates(), grade, today);
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const pct = this.pct().trim();
    if (!PCT.test(pct)) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = this.from().trim();
    if (from !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
      this.error.set('Type a from-date as YYYY-MM-DD, or leave it blank.');
      return;
    }
    this.submitting = true;
    try {
      const rate = await this.service.set(sheet, this.grade(), pct, from || null);
      if (this.session.sheetId() !== sheet) return;
      this.saved.emit(rate);
      this.pct.set('');
      this.from.set('');
    } catch {
      this.error.set('That rate could not be set.');
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim, cents } from './claims.service';
import { Grade } from './people.service';

export interface Rate {
  grade: Grade;
  /** The percent with two decimals, as text (e.g. "12.50"). */
  pct: string;
  /** The date the rate applies from (YYYY-MM-DD); null when it applies from the beginning of time. */
  from: string | null;
}

/** The grade's rate in force on a date: the one with the latest from-date on or before it, or the
 *  one with no from-date when none has; null when no rate applies yet. */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct ?? null;
}

/** What is due on an amount at a rate: amount times pct, divided by 100, rounded half to even to
 *  two decimals; null when there is no rate. Worked in whole cents and hundredths of a percent, so
 *  it is exact. */
export function dueCents(amountCents: number, pct: string | null): number | null {
  if (pct === null) return null;
  const product = BigInt(amountCents) * BigInt(Math.round(Number(pct) * 100));
  const negative = product < 0n;
  const abs = negative ? -product : product;
  let quotient = abs / 10000n;
  const remainder = abs % 10000n;
  if (remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n)) quotient += 1n;
  return Number(negative ? -quotient : quotient);
}

/** What is due on a claim, in cents: a claim settled at a rate keeps what was due on it then; a
 *  claim a statement bound keeps the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at its person's grade's rate in force on the claim's date, null when
 *  none applies then. */
export function claimDueCents(claim: Claim, rates: Rate[], grade: Grade): number | null {
  if (claim.status === 'SETTLED' && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated) return claim.statedDue === null ? null : cents(claim.statedDue);
  return dueCents(cents(claim.amount), rateOn(rates, grade, claim.date));
}

// The rates of the grades on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class RatesService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheet), { headers: this.session.headers() }));
  }

  /** A null from sets the rate that applies from the beginning of time. */
  set(sheet: string, grade: Grade, pct: string, from: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheet)}/${grade}`, { pct, from }, { headers: this.session.headers() }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
